export const ITEMS = ROWS.map(([id, name, price, onMrp, cat, kcal, qty, story, own, lib, borrow, best], i) => {
  const pics = [...own.map(C), ...borrow.flatMap((k) => (PICKS[k] || []).map(C)), ...lib.flatMap((k) => [photo(k), ...extraPhotos(k)])].filter(Boolean);
  const gallery = [...new Set(pics)].slice(0, 5);
  return {
    id, restaurantId: 'parag', name, price, ...(onMrp ? { onMrp: true } : {}), cat, kcal, qty, desc: '', story,
    img: gallery[0] || '', gallery, veg: true, available: true, bestseller: !!best, sort: 100 + i, menuPack: 'parag-v1',
  };
});
